750	// renderTagEndsWith generates SQL for tags.exists(t, t.endsWith("suffix")).
751	func (r *renderer) renderTagEndsWith(field Field, suffix string, _ ComprehensionKind) (renderResult, error) {
752		arrayExpr := jsonArrayExpr(r.dialect, field)
753		pattern := fmt.Sprintf(`%%%s"%%`, suffix)
754	
755		likeExpr := r.buildJSONArrayLike(arrayExpr, pattern)
756		return renderResult{sql: r.wrapWithNullCheck(arrayExpr, likeExpr)}, nil
757	}
758	
759	// renderTagContains generates SQL for tags.exists(t, t.contains("substring")).
760	func (r *renderer) renderTagContains(field Field, substring string, _ ComprehensionKind) (renderResult, error) {
761		arrayExpr := jsonArrayExpr(r.dialect, field)
762		pattern := fmt.Sprintf(`%%%s%%`, substring)
763	
764		likeExpr := r.buildJSONArrayLike(arrayExpr, pattern)
765		return renderResult{sql: r.wrapWithNullCheck(arrayExpr, likeExpr)}, nil
766	}
